using System;using System.Diagnostics;using System.Linq;using System.IO;using System.Collections.Generic;
namespace LoopPedal {
static class RealtimeChecks {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static float[] Floats(byte[] bytes){float[] a=new float[bytes.Length/4];Buffer.BlockCopy(bytes,0,a,0,bytes.Length);return a;}
 static Engine SendFixture(bool a,bool b,int send,int route){var e=new Engine();e.Partner=new Engine();e.Partner.ClockLeader=e;e.Fx.Routing=route;e.Fx.GrainMode=2;e.Fx.GrainMix=.8f;e.Fx.DelaySync=false;e.Fx.Time=.04f;e.Fx.Size=.3f;e.Fx.Filter=.3f;e.Partner.Fx.Filter=-.4f;for(int bank=0;bank<2;bank++){if(bank==0?!a:!b)continue;var source=new float[96000];for(int i=0;i<48000;i++)source[2*i]=source[2*i+1]=(float)(.025*Math.Sin(i*(bank==0?.043:.071))*Math.Exp(-(i%9000)/3000.0));var owner=bank==0?e:e.Partner;owner.Layers.Add(new Layer{Name=bank==0?"A":"B",Original=source,Audio=source});owner.LoopFrames=48000;}var fx=send==0?e.Fx:e.Partner.Fx;fx.Reverb=.4f;fx.Delay=.3f;fx.Grain=.7f;return e;}
 static float[] SendAudio(Engine e){var provider=new LoopProvider(e);var bytes=new byte[48000*8];provider.Read(bytes,0,bytes.Length);return Floats(bytes);}
 static void BankSends(List<string> lines){for(int route=0;route<3;route++)for(int bank=0;bank<2;bank++)using(var mixed=SendFixture(true,true,bank,route))using(var a=SendFixture(true,false,bank,route))using(var b=SendFixture(false,true,bank,route)){var both=SendAudio(mixed);var one=SendAudio(a);var two=SendAudio(b);double max=0;for(int i=0;i<both.Length;i++)max=Math.Max(max,Math.Abs(both[i]-one[i]-two[i]));Check(max<.000001,"Independent bank sends route="+route+" bank="+bank+" max="+max);Check(mixed.Partner.Fx.Routing==route&&mixed.Partner.Fx.GrainMix==.8f,"Shared FX settings");Check(bank==0?mixed.Partner.Fx.Grain==0:mixed.Fx.Grain==0,"Other bank send must remain zero");lines.Add("PASS independent FX sends bank="+bank+" route="+route+" error="+max);} }
 public static void Run(){var lines=new List<string>();try{
 using(var e=new Engine()){var source=new float[96000];for(int i=0;i<48000;i++)source[i*2]=source[i*2+1]=(float)(.1*Math.Sin(i*.04));for(int i=0;i<8;i++)e.Layers.Add(new Layer{Name="Idle probe",Original=source,Audio=source});var provider=new LoopProvider(e);var bytes=new byte[4096];for(int j=0;j<100;j++)provider.Read(bytes,0,bytes.Length);e.Playing=false;var timer=Stopwatch.StartNew();double latePeak=0;for(int block=0;block<56250;block++){provider.Read(bytes,0,bytes.Length);if(block%500==0&&block>200){var a=Floats(bytes);foreach(float v in a)latePeak=Math.Max(latePeak,Math.Abs(v));}}timer.Stop();Check(latePeak==0,"Stopped playback must remain exactly silent");Check(e.Layers.All(x=>x.SmoothL==0&&x.SmoothR==0),"No subnormal stopped gains");Check(provider.SleepingFxBlocks>50000,"Idle FX sleep");lines.Add("PASS 10 simulated minutes stopped: exact digital silence, eight layers, "+timer.ElapsedMilliseconds+" ms CPU wall time; idle FX blocks="+provider.SleepingFxBlocks);}
 for(int mode=0;mode<3;mode++){using(var e=new Engine()){var source=new float[96000];for(int i=0;i<48000;i++)source[i*2]=source[i*2+1]=(float)(.08*Math.Sin(i*.05));e.Layers.Add(new Layer{Original=source,Audio=source});e.Fx.Reverb=.5f;e.Fx.Delay=.5f;e.Fx.Grain=.7f;e.Fx.GrainMode=2;e.Fx.DelayMode=mode;var provider=new LoopProvider(e);var bytes=new byte[4096];for(int j=0;j<94;j++)provider.Read(bytes,0,bytes.Length);e.Playing=false;double latePeak=0;for(int j=0;j<11250;j++){provider.Read(bytes,0,bytes.Length);if(j>10000){var a=Floats(bytes);foreach(float v in a){Check(!float.IsNaN(v)&&!float.IsInfinity(v),"Finite idle tail");latePeak=Math.Max(latePeak,Math.Abs(v));}}}Check(latePeak<.0001,"Idle FX produced an audible burst: "+latePeak);lines.Add("PASS two-minute stopped Hall/Cloud Delay soak, delay type "+mode+", late peak="+latePeak+", sleeping blocks="+provider.SleepingFxBlocks);}}
 using(var a=new Engine())using(var b=new Engine()){a.Partner=b;b.ClockLeader=a;a.LoopFrames=48000;var baseAudio=Enumerable.Repeat(.1f,96000).ToArray();a.Layers.Add(new Layer{Original=baseAudio,Audio=baseAudio});var input=new Input(new SourceChoice{Name="Monitor input",Left=0,Right=1});a.Inputs.Add(input);a.SetInputMonitor(true);a.Begin(true);b.InputMode=1;b.Sync=true;b.BPM=240;b.Begin(false);var provider=new LoopProvider(a);var bytes=new byte[4096];var live=Enumerable.Repeat(.2f,1024).ToArray();for(int j=0;j<94;j++){input.Feed(live,live.Length,2,a.AudioFrame);provider.Read(bytes,0,bytes.Length);}var output=Floats(bytes);Check(output.All(v=>Math.Abs(v-.3f)<.00001),"Monitor heard once at unity alongside loop");a.Finish(false);b.Finish(false);Check(a.Layers.Last().Original.All(v=>v==.2f),"Monitor must not self-record");Check(b.Layers.Single().Original.Skip(8192).All(v=>Math.Abs(v-.1f)<.000001),"Monitor excluded from A-to-B feed");a.Playing=b.Playing=false;a.SetInputMonitor(false);for(int j=0;j<100;j++){input.Feed(live,live.Length,2,a.AudioFrame);provider.Read(bytes,0,bytes.Length);}Check(Floats(bytes).All(v=>v==0),"Monitor OFF digital silence");lines.Add("PASS headphone monitor unity, smooth-off silence, raw capture and clean A-to-B isolation");}
 double[] energies=new double[6];for(int order=0;order<6;order++){var fx=new MasterFx{SerialOrder=order,GrainMode=2,Grain=.7f,GrainMix=.7f,Reverb=.5f,Delay=.4f,DelaySync=false,Time=.04f,CloudFeedback=.3f};for(int i=0;i<144000;i++){float source=i<48000?(float)(.1*Math.Sin(i*.03)*Math.Exp(-(i%12000)/2000.0)):0,l,r;fx.Process(source,source*.8f,out l,out r);Check(!float.IsNaN(l)&&!float.IsInfinity(l),"Finite serial order");if(i>48000)energies[order]+=l*l+r*r;}Check(fx.Copy().SerialOrder==order,"Export order copy");}for(int i=0;i<6;i++)for(int j=0;j<i;j++)Check(Math.Abs(energies[i]-energies[j])>.00001,"Audio route order must really change DSP");lines.Add("PASS six distinct actual serial effect chains and export order copies");
 BankSends(lines);CaptureChecks.Run(lines);FreezeChecks.Run(lines);CloudyChecks.Run(lines);File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"realtime-stability-tests.txt"),lines);
 }catch(Exception e){lines.Add("FAIL "+e);File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"realtime-stability-tests.txt"),lines);Environment.ExitCode=1;}}
}
}
